cd /workspace && cat > src/service.ts <<'EOF'
import { Actor, Document } from './types';
import { DocumentRepository } from './repository';
export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    // Visibility: active (not deleted) documents in the actor's tenant only.
    const document = this.repository.documents.find(
      row => row.id === id && row.tenant === actor.tenant && !row.deleted
    );
    if (!document) throw new Error('not found');
    if (!this.canArchive(actor, document)) throw new Error('forbidden');
    if (!document.archived) this.repository.archive(document, actor.user);
  }
  private canArchive(actor: Actor, document: Document): boolean {
    switch (actor.role) {
      case 'admin': return true;
      case 'editor': return document.owner === actor.user;
      default: return false; // viewers and unknown roles are denied
    }
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

// authorization checks
{
  const mk = () => new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'gone', tenant: 'a', owner: 'e', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
    { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
  ]);
  const r = mk(); const s = new DocumentService(r);
  const editor = { tenant: 'a', user: 'e', role: 'editor' };
  const viewer = { tenant: 'a', user: 'e', role: 'viewer' };
  const adm = { tenant: 'a', user: 'adm', role: 'admin' };
  const snap = () => JSON.stringify([r.documents, r.audit]);
  const before = snap();
  for (const id of ['gone', 'foreign', 'missing']) assert.throws(() => s.archive(adm, id), /^Error: not found$/);
  assert.throws(() => s.archive(editor, 'other'), /^Error: forbidden$/);
  assert.throws(() => s.archive(viewer, 'own'), /^Error: forbidden$/);
  assert.throws(() => s.archive(viewer, 'done'), /^Error: forbidden$/);
  assert.throws(() => s.archive(editor, 'done'), /^Error: forbidden$/);
  assert.equal(snap(), before);
  s.archive(editor, 'own');
  s.archive(adm, 'other');
  s.archive(adm, 'done');
  assert.deepEqual(r.audit, [{ actor: 'e', document: 'own' }, { actor: 'adm', document: 'other' }]);
}
EOF
tsc -p tsconfig.json && node checks/public.cjs && echo OK

content.text:
`DocumentService.archive` in `src/service.ts` now enforces the authorization rules. `tsc -p tsconfig.json && node checks/public.cjs` passes, including the new checks.

- **Visibility:** The service looks for a document with the given id that is in the actor's tenant and not deleted. If there isn't one, it throws `Error('not found')`. That covers missing, deleted and foreign-tenant documents, and admins get no exception. It searches `repository.documents` directly rather than using `repository.find`. `find` returns the first row with a matching id, so a foreign-tenant or deleted row with the same id could hide a visible one.
- **Permission:** An admin may archive any visible document. An editor may archive only documents they own. A viewer, or any unrecognized role, gets `Error('forbidden')`.
- **Order of checks:** Permission is checked before the already-archived check. A forbidden actor therefore gets `forbidden` even on an already archived document.
- **Success and repeats:** Archiving an unarchived document goes through the existing `repository.archive`. That sets `archived` to true and appends `{actor: actor.user, document: id}` to the audit log. Repeating the call on an archived document by an authorized actor does nothing.
- **Failures:** Every check runs before anything is written, so a failed call changes no document and no audit entry.

I appended checks to `checks/public.cjs`. They cover:
- not-found cases, including admin on deleted, foreign-tenant and missing documents;
- editor and viewer `forbidden` cases, including on an archived document;
- state and audit unchanged after failures;
- successful editor and admin archives;
- the no-op repeat.

I didn't change any public interfaces.
